package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class SaleReturnTest extends SaleFixture {
 JsonNode sale(String quantity)throws Exception{return sell(input(UUID.randomUUID(),quantity,"10.25","200"),201);}
 String path(JsonNode sale){return "/api/v1/pos/sales/"+sale.get("id").asText()+"/returns";}
 JsonNode current(JsonNode sale)throws Exception{return getApi("/api/v1/pos/sales/"+sale.get("id").asText(),auth,200);}
 Map<String,Object> returnedItem(String product,String quantity){return Map.of("productId",product,"quantity",quantity);}
 Map<String,Object> refund(String payment,String amount,String reference){return Map.of("paymentId",payment,"amount",amount,"reference",reference);}
 Map<String,Object> body(JsonNode sale,UUID key,long version,String quantity,String amount){return Map.of("requestId",key,"sessionId",session,"version",version,"note","Devolução conferida do item","externalRefundsConfirmed",false,"items",List.of(returnedItem(product,quantity)),"refunds",new BigDecimal(amount).signum()==0?List.of():List.of(refund(sale.get("payments").get(0).get("id").asText(),amount,"")));}
 JsonNode postReturn(JsonNode sale,Object body,int status)throws Exception{return postApi(path(sale),auth,body,status);}
 Map<String,Object> cancelBody(long version){return Map.of("requestId",UUID.randomUUID(),"version",version,"note","Cancelamento conferido","externalRefundsConfirmed",true);}
 void close(long version,String count)throws Exception{postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",version,"countedAmount",count,"note","Fechamento conferido"),200);}
 void reopen(String opening)throws Exception{session=postApi("/api/v1/pos/cash-sessions",auth,Map.of("requestId",UUID.randomUUID(),"terminalId",terminal,"openingAmount",opening,"note","Nova abertura conferida"),201).get("id").asText();}
 @Test void partialReturnRestoresStockCostAndOnlyRefundsHistoricalAmount()throws Exception{var sale=sale("2");var result=postReturn(sale,body(sale,UUID.randomUUID(),0,"0.5","5.13"),201);money("5.13",result.get("total"));assertEquals(0,new BigDecimal("8.5").compareTo(quantity(product)));assertEquals(0,new BigDecimal("15.37").compareTo(balance()));var s=current(sale);assertEquals("PARTIALLY_RETURNED",s.get("commercialStatus").asText());assertEquals("PARTIALLY_REFUNDED",s.get("financialStatus").asText());money("5.13",s.get("refundedAmount"));money("0.5",s.get("items").get(0).get("returnedQuantity"));assertEquals("PARTIAL",s.get("payments").get(0).get("refundStatus").asText());assertEquals(1,s.get("version").asInt());assertEquals(2,getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("version").asInt());}
 @Test void cumulativeRoundingReconcilesFullReturnToOriginalItemTotal()throws Exception{var sale=sale("2");postReturn(sale,body(sale,UUID.randomUUID(),0,"0.5","5.13"),201);postReturn(sale,body(sale,UUID.randomUUID(),1,"0.5","5.12"),201);postReturn(sale,body(sale,UUID.randomUUID(),2,"1","10.25"),201);var s=current(sale);money("20.50",s.get("refundedAmount"));assertEquals("RETURNED",s.get("commercialStatus").asText());assertEquals("REFUNDED",s.get("financialStatus").asText());assertEquals("FULL",s.get("payments").get(0).get("refundStatus").asText());assertEquals(0,balance().signum());assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));postReturn(sale,body(sale,UUID.randomUUID(),3,"0.1","1.02"),409);}
 @Test void replayAfterClosingDoesNotReturnOrRefundAgain()throws Exception{var sale=sale("2");var body=body(sale,UUID.randomUUID(),0,"1","10.25");var result=postReturn(sale,body,201);close(2,"10.25");assertEquals(result,postReturn(sale,body,201));assertEquals(3,count("stock_operation"));assertEquals(2,count("treasury_operation"));var changed=new HashMap<>(body);changed.put("note","Justificativa alterada");postReturn(sale,changed,409);}
 @Test void newShiftCanRefundClosedSaleWithoutChangingFrozenOriginalDrawer()throws Exception{var sale=sale("2");String original=session;close(1,"20.50");reopen("20.50");postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),201);money("20.50",getApi("/api/v1/pos/cash-sessions/"+original,auth,200).get("expectedAmount"));money("10.25",getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("expectedAmount"));}
 @Test void refundCanUseDifferentDrawerOfSameBranch()throws Exception{var sale=sale("2");String originalAccount=account;close(1,"20.50");account=postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code","NEW","name","Outro caixa","kind","CASH"),201).get("id").asText();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"destinationId",account,"amount","50","note","Fundo real informado de teste"),200);terminal=postApi("/api/v1/pos/terminals",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"accountId",account,"code","NEW","name","Outro terminal"),201).get("id").asText();reopen("50");var r=postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),201);assertEquals(account,r.get("refunds").get(0).get("accountId").asText());assertEquals(0,new BigDecimal("39.75").compareTo(balance()));money("20.50",getApi("/api/v1/treasury/accounts/"+originalAccount,auth,200).get("balance"));}
 @Test void zeroCentReturnCanRestoreFractionalStockWithoutFinanceOperation()throws Exception{var sale=sale("1");var r=postReturn(sale,body(sale,UUID.randomUUID(),0,"0.000001","0"),201);money("0",r.get("total"));assertEquals(0,r.get("refunds").size());assertEquals(1,count("treasury_operation"));assertEquals("PARTIALLY_RETURNED",current(sale).get("commercialStatus").asText());assertEquals("PAID",current(sale).get("financialStatus").asText());postReturn(sale,body(sale,UUID.randomUUID(),1,"0.999999","10.25"),201);assertEquals(0,balance().signum());}
 @Test void overReturningAndWrongRefundTotalRollbackEverything()throws Exception{var sale=sale("2");postReturn(sale,body(sale,UUID.randomUUID(),0,"3","30.75"),409);postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.24"),400);assertEquals(0,count("pos_sale_return"));assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));}
 @Test void cancellationCannotFollowEvenZeroValueReturnAndCancelledSaleCannotReturn()throws Exception{var sale=sale("2");postReturn(sale,body(sale,UUID.randomUUID(),0,"0.000001","0"),201);postApi("/api/v1/pos/sales/"+sale.get("id").asText()+"/cancel",auth,cancelBody(1),409);var other=sale("1");postApi("/api/v1/pos/sales/"+other.get("id").asText()+"/cancel",auth,cancelBody(0),200);postReturn(other,body(other,UUID.randomUUID(),1,"1","10.25"),409);}
 @Test void closedRefundSessionAndStaleSaleVersionAreRejected()throws Exception{var sale=sale("2");postReturn(sale,body(sale,UUID.randomUUID(),1,"1","10.25"),409);close(1,"20.50");postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),409);assertEquals(0,count("pos_sale_return"));}
 @Test void insufficientDrawerBalanceRollsBackStockAndHistory()throws Exception{var sale=sale("2");postApi("/api/v1/pos/cash-sessions/"+session+"/movements",auth,Map.of("requestId",UUID.randomUUID(),"kind","WITHDRAW","amount","20","note","Retirada posterior de teste"),200);postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),409);assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));assertEquals(0,count("pos_sale_return"));assertEquals(2,count("stock_operation"));assertEquals(0,current(sale).get("version").asInt());}
 @Test void inactiveProductMayReturnButUnitChangeAndInactiveWarehouseReject()throws Exception{var sale=sale("2");db.update("UPDATE product SET unit='UN' WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),409);db.update("UPDATE product SET unit='KG',active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));db.update("UPDATE warehouse SET active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),404);db.update("UPDATE warehouse SET active=TRUE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),201);}
 @Test void permissionsTenantAndBranchScopeApplyToReturnHistoryAndReplay()throws Exception{var sale=sale("2");var body=body(sale,UUID.randomUUID(),0,"1","10.25");var r=postReturn(sale,body,201);String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi(path(sale),token(other),404);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:return'",tenant);postReturn(sale,body,403);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) SELECT tenant_id,id,'pos:return' FROM app_user WHERE tenant_id=?",tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);getApi(path(sale),auth,404);getApi(path(sale)+"/"+r.get("id").asText(),auth,404);postReturn(sale,body,404);}
 @Test void duplicateProductsAndPaymentsAreRejected()throws Exception{var sale=sale("2");var body=new HashMap<>(body(sale,UUID.randomUUID(),0,"1","10.25"));body.put("items",List.of(returnedItem(product,"0.5"),returnedItem(product,"0.5")));postReturn(sale,body,400);body.put("items",List.of(returnedItem(product,"1")));String p=sale.get("payments").get(0).get("id").asText();body.put("refunds",List.of(refund(p,"5",""),refund(p,"5.25","")));postReturn(sale,body,400);assertEquals(0,count("pos_sale_return"));}
 @Test void concurrentReplayHasOnlyOneEffect()throws Exception{var sale=sale("2");var body=body(sale,UUID.randomUUID(),0,"1","10.25");assertEquals(List.of(201,201),raceReturns(path(sale),body,path(sale),body));assertEquals(1,count("pos_sale_return"));assertEquals(0,new BigDecimal("9").compareTo(quantity(product)));assertEquals(0,new BigDecimal("10.25").compareTo(balance()));}
 @Test void concurrentReturnsCannotSpendSameQuantityOrPaymentTwice()throws Exception{var sale=sale("2");assertEquals(List.of(201,409),raceReturns(path(sale),body(sale,UUID.randomUUID(),0,"1.5","15.38"),path(sale),body(sale,UUID.randomUUID(),0,"1.5","15.38")));assertEquals(1,count("pos_sale_return"));assertEquals(0,new BigDecimal("9.5").compareTo(quantity(product)));}
 @Test void closeRaceWithReturnPreservesFrozenAmountAndStock()throws Exception{var sale=sale("2");var statuses=raceReturns(path(sale),body(sale,UUID.randomUUID(),0,"1","10.25"),"/api/v1/pos/cash-sessions/"+session+"/close",Map.of("requestId",UUID.randomUUID(),"version",1,"countedAmount","20.50","note","Fechamento concorrente"));assertTrue(statuses.equals(List.of(200,409))||statuses.equals(List.of(201,409)));var s=getApi("/api/v1/pos/cash-sessions/"+session,auth,200);if(s.get("status").asText().equals("CLOSED")){money("20.50",s.get("expectedAmount"));assertEquals(0,count("pos_sale_return"));}else{money("10.25",s.get("expectedAmount"));assertEquals(1,count("pos_sale_return"));}}
 JsonNode bankSale()throws Exception{String bank=postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code","BANK","name","Banco","kind","BANK"),201).get("id").asText();return sell(Map.of("requestId",UUID.randomUUID(),"sessionId",session,"items",List.of(item(product,"2","10.25")),"payments",List.of(Map.of("method","CASH","amount","5.50","tendered","10"),Map.of("method","PIX","amount","15","accountId",bank,"reference","Recebimento "+UUID.randomUUID(),"confirmed",true))),201);}
 @Test void mixedRefundsRespectOriginalPaymentBalancesAndReferences()throws Exception{var sale=bankSale();var body=new HashMap<>(body(sale,UUID.randomUUID(),0,"1","10.25"));String cash=sale.get("payments").get(0).get("id").asText(),bank=sale.get("payments").get(1).get("id").asText();body.put("externalRefundsConfirmed",true);body.put("refunds",List.of(refund(cash,"5.50",""),refund(bank,"4.75","Estorno parcial 1")));var result=postReturn(sale,body,201);assertEquals(2,result.get("refunds").size());assertEquals(0,balance().signum());var rest=new HashMap<>(body(sale,UUID.randomUUID(),1,"1","10.25"));rest.put("externalRefundsConfirmed",true);rest.put("refunds",List.of(refund(bank,"10.25","Estorno parcial 2")));postReturn(sale,rest,201);assertEquals("REFUNDED",current(sale).get("financialStatus").asText());}
 @Test void bankRefundRequiresConfirmationAndNewProofAndEnoughFunds()throws Exception{var sale=bankSale();String bank=sale.get("payments").get(1).get("id").asText();var body=new HashMap<>(body(sale,UUID.randomUUID(),0,"0.5","5.13"));body.put("refunds",List.of(refund(bank,"5.13","Estorno parcial")));postReturn(sale,body,400);body.put("externalRefundsConfirmed",true);postReturn(sale,body,201);var second=new HashMap<>(body(sale,UUID.randomUUID(),1,"0.5","5.12"));second.put("externalRefundsConfirmed",true);second.put("refunds",List.of(refund(bank,"5.12","Estorno parcial")));postReturn(sale,second,409);second.put("refunds",List.of(refund(bank,"5.12","Outro estorno")));String bankAccount=sale.get("payments").get(1).get("accountId").asText();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"sourceId",bankAccount,"amount","9.87","note","Saída posterior no banco"),200);postReturn(sale,second,409);assertEquals(1,count("pos_sale_return"));}
 @Test void paymentAllocationCannotExceedOriginalCashEvenIfDrawerHasMoreMoney()throws Exception{var sale=bankSale();postApi("/api/v1/pos/cash-sessions/"+session+"/movements",auth,Map.of("requestId",UUID.randomUUID(),"kind","SUPPLY","amount","100","note","Reforço de fundo de teste"),200);postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),409);assertEquals(0,count("pos_sale_return"));}
 @Test void operatorRequiresOwnCurrentSessionOrExplicitSupervision()throws Exception{var sale=sale("2");var u=postApi("/api/v1/users",auth,Map.of("name","Outro","email","other@example.com","password",password,"permissions",List.of("pos:read","pos:return","treasury:read","treasury:move")),201);String other=postApi("/api/v1/auth/login",null,Map.of("company",company,"email","other@example.com","password",password),200).get("token").asText();var body=body(sale,UUID.randomUUID(),0,"1","10.25");postApi(path(sale),other,body,403);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) VALUES(?,?,'pos:supervise')",tenant,UUID.fromString(u.get("id").asText()));postApi(path(sale),other,body,201);}
 @Test void returnKeepsOriginalCostAfterDifferentPricedReceipt()throws Exception{var sale=sale("2");postApi("/api/v1/inventory/movements",auth,Map.of("operationId",UUID.randomUUID(),"warehouseId",warehouse,"productId",product,"type","RECEIPT","quantity","2","unitCost","9","reason","Entrada com custo diferente"),200);postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),201);assertEquals(0,new BigDecimal("4.090909").compareTo(db.queryForObject("SELECT average_cost FROM stock_balance WHERE tenant_id=? AND warehouse_id=? AND product_id=?",BigDecimal.class,tenant,UUID.fromString(warehouse),UUID.fromString(product))));}
 @Test void returnRequestIdCannotBeReusedForDifferentSale()throws Exception{var sale=sale("2");UUID key=UUID.randomUUID();postReturn(sale,body(sale,key,0,"1","10.25"),201);var other=sale("1");postReturn(other,body(other,key,0,"1","10.25"),409);}
 @Test void failureOnSecondStockItemRollsBackFirstReturn()throws Exception{String second=createProduct("SECOND","10.25");stock(second,"10");var sale=sell(Map.of("requestId",UUID.randomUUID(),"sessionId",session,"tendered","100","items",List.of(item(product,"1","10.25"),item(second,"1","10.25"))),201);String changed=UUID.fromString(product).compareTo(UUID.fromString(second))>0?product:second;db.update("UPDATE product SET unit='UN' WHERE tenant_id=? AND id=?",tenant,UUID.fromString(changed));var body=new HashMap<>(body(sale,UUID.randomUUID(),0,"1","20.50"));body.put("items",List.of(returnedItem(product,"1"),returnedItem(second,"1")));postReturn(sale,body,409);assertEquals(0,new BigDecimal("9").compareTo(quantity(product)));assertEquals(0,new BigDecimal("9").compareTo(quantity(second)));assertEquals(4,count("stock_operation"));assertEquals(0,count("pos_sale_return"));}
 @Test void refundSessionMustBelongToSaleBranch()throws Exception{var sale=sale("2");close(1,"20.50");UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra filial"),201).get("id").asText());account=postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",other,"code","OTHER","name","Outro caixa","kind","CASH"),201).get("id").asText();terminal=postApi("/api/v1/pos/terminals",auth,Map.of("requestId",UUID.randomUUID(),"branchId",other,"accountId",account,"code","OTHER","name","Outro terminal"),201).get("id").asText();reopen("0");postReturn(sale,body(sale,UUID.randomUUID(),0,"1","10.25"),400);assertEquals(0,count("pos_sale_return"));}
 @Test void bankScopeIsRevalidatedEvenWhenReplayingReturn()throws Exception{var sale=bankSale();String payment=sale.get("payments").get(1).get("id").asText();UUID bank=UUID.fromString(sale.get("payments").get(1).get("accountId").asText());var body=new HashMap<>(body(sale,UUID.randomUUID(),0,"1","10.25"));body.put("externalRefundsConfirmed",true);body.put("refunds",List.of(refund(payment,"10.25","Comprovante")));postReturn(sale,body,201);UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());db.update("UPDATE treasury_account SET branch_id=? WHERE tenant_id=? AND id=?",other,tenant,bank);UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,branch);postReturn(sale,body,404);assertEquals(1,count("pos_sale_return"));}
 List<Integer> raceReturns(String path1,Object body1,String path2,Object body2)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status(path1,body1);});var b=pool.submit(()->{gate.await();return status(path2,body2);});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);return result;}}
}
